candidates.pseudocode:
isStrongBullTrendBar = close[0] > open[0] && (close[0] - open[0]) >= strongBodyFraction * (high[0] - low[0]);
limitPrice = close[0];
enterLongOnLimitNextBar = isStrongBullTrendBar && isStrongBullSpike[0] && low[1] <= limitPrice;

isMeasuringGapCandidate = low[1] > high[2]; // breakout bar's low clears the bar before it: a micro gap
limitPrice = high[2] + gapEntryTicks * tickSize;
enterLongOnLimitNextBar = isMeasuringGapCandidate && low[1] <= limitPrice;

isInsideBar1 = high[1] < high[2] && low[1] > low[2];
isInsideBar0 = high[0] < high[1] && low[0] > low[1];
isIiPattern = isInsideBar1 && isInsideBar0;
iiPatternBottom = min(low[0], low[1]);

isStrongBullTrendBar0 = close[0] > open[0] && (close[0] - open[0]) >= strongBodyFraction * (high[0] - low[0]);
isStrongBullTrendBar1 = close[1] > open[1] && (close[1] - open[1]) >= strongBodyFraction * (high[1] - low[1]);
limitPrice = low[0];
enterLongOnLimitNextBar = isOpeningRangeStillForming[0] && isStrongBullTrendBar0 && isStrongBullTrendBar1 && low[1] <= limitPrice;

needsConfirmationBarForFlipDown = isBearSpike[0] && isBullMarket[0] && wouldFlipAlwaysInShortIfNextBarBearish[0];
limitPriceAtClose = close[0];
limitPriceAtLow = low[0];
enterLongOnLimitNextBar = needsConfirmationBarForFlipDown && (low[1] <= limitPriceAtLow);
// if bar[1] closes without a bear body, also buy its close, and place a stop entry above its high

isLikelySellClimax = isLargeBearTrendBar[0] && (isEndOfBearTrend[0] || isPullbackInBullTrend[0]);
limitPriceAtClose = close[0];
limitPriceAtLow = low[0];
enterLongOnLimitNextBar = isLikelySellClimax && low[1] <= limitPriceAtLow;

isOneBarBullSpike = isBullSpikeBar[1] && !isBullSpikeBar[2]; // spike is exactly one bar wide
limitPrice = low[1] + pullbackTicks * tickSize;
enterLongOnLimitNextBar = isOneBarBullSpike && isPullbackInProgress[0] && low[0] <= limitPrice;

originalSignalBarHigh = spikeSignalBarHigh; // recorded once at the spike, held indefinitely
limitPrice = originalSignalBarHigh + testTicks * tickSize;
enterLongOnLimitNextBar = isSecondLegLikely[0] && low[0] <= limitPrice;

hadStrongBullRunRecently = countStrongBullTrendBars(lookback = twoBarsMin) >= twoBarsMin;
isBearCloseBar = close[0] < open[0];
enterLongAtClose = hadStrongBullRunRecently && isBearCloseBar && isStartOfStrongBullSwing[0];

isWeakSignalBar = (close[0] - low[0]) / (high[0] - low[0] + epsilon) < weakCloseThreshold;
limitPrice = low[0];
enterLongOnLimitNextBar = (isLow1SetupSignalBar[0] || isLow2SetupSignalBar[0]) && isWeakSignalBar
   && (isAtBottomOfTradingRange[0] || isNewBullTrendAfterStrongReversal[0]) && low[1] <= limitPrice;

bearScalpTargetPrice = bearSignalBarLow[0] - scalperTargetTicks * tickSize;
limitPrice = bearScalpTargetPrice + fadeOffsetTicks * tickSize;
enterLongOnLimitNextBar = isStrongBullTrend[0] && isShortScalpSetup[0] && low[1] <= limitPrice;

hasNotDroppedFarBelowMA = close[0] >= movingAverage[0] - maxMaPenetrationTicks * tickSize;
isSmallBearTrendBar = close[0] < open[0] && (high[0] - low[0]) <= smallBarRangeTicks * tickSize;
closeNearBelowMA = movingAverage[0] - close[0] <= closeToleranceTicks * tickSize && close[0] < movingAverage[0];
enterLongAtClose = isVeryStrongBullTrend[0] && hasNotDroppedFarBelowMA && isSmallBearTrendBar && closeNearBelowMA && isFirstSuchBarSinceTrendStart;

isSteeplyRisingMA = (movingAverage[0] - movingAverage[maSlopeLookback]) / maSlopeLookback >= minMaSlopePerBar;
limitPriceLevel_k = movingAverage[0] - k * intervalDistance; // k = 1..numScaleInLevels
enterLongOnLimitNextBar_k = isSteeplyRisingMA && low[1] <= limitPriceLevel_k;

isBullFlagBreakoutBar = isBullTrendBar[0] && high[0] > bullFlagHigh[0];
limitPrice = low[0];
enterLongOnLimitNextBar = isBullFlagBreakoutBar && low[1] <= limitPrice;

lowerRangeHeight = lowerRangeHigh[0] - lowerRangeLow[0];
measuredMoveTarget = lowerRangeHigh[0] + lowerRangeHeight;
limitPrice = measuredMoveTarget - fadeOffsetTicks * tickSize;
enterShortOnLimitNextBar = isTrendingTradingRangeDay[0] && high[1] >= limitPrice;

isBearCloseBar = close[0] < open[0];
closeInTopHalfOfPriorBar = (close[0] - low[1]) / (high[1] - low[1] + epsilon) > 0.5;
enterShortAtClose = isTradingRangeDay[0] && isBullSpike[0] && isNearTopOfRange[0] && isBearCloseBar
   && closeInTopHalfOfPriorBar && isSecondReversalAttempt[0];

isLargeBullTrendBar = close[0] > open[0] && (high[0] - low[0]) >= largeBarRangeTicks * tickSize;
nearMeasuredMoveTarget = abs(high[0] - measuredMoveTarget[0]) <= nearTargetTicks * tickSize;
recentSellingPressure = countBearTrendBars(lookback = pressureLookback) >= minPressureBars;
limitPrice = high[0];
enterShortAtClose = isBullTrendingRangeDay[0] && isLargeBullTrendBar && nearMeasuredMoveTarget && recentSellingPressure;
enterShortOnLimitNextBar = isBullTrendingRangeDay[0] && isLargeBullTrendBar && nearMeasuredMoveTarget && recentSellingPressure && high[1] >= limitPrice;

twoBarReversalUpForming = isBearTrendBar[1] && close[0] > open[0]; // first bar bearish, second (forming) bar so far bullish
limitPrice = high[1];
enterShortOnLimitCurrentBar = isStrongBearChannel[1] && twoBarReversalUpForming && high[0] >= limitPrice;

legHigh = currentLegHigh[0];
legLow = currentLegLow[0];
limitPrice = legHigh - retracementFraction * (legHigh - legLow);
enterLongOnLimitNextBar = isBullTrend[0] && low[1] <= limitPrice;

entryBarLow = low[entryBarIndex]; // recorded at entry
retestedEntryBarLow = countTouchesOfLevel(entryBarLow, sinceBars = ctx.BarsSinceEntry()) >= minRetests;
limitPrice = entryBarLow + addOnTicks * tickSize;
enterOrAddLongOnLimitNextBar = retestedEntryBarLow && low[0] <= limitPrice;

lineValue = trendLineValue(fadedLine, currentBarIndex); // long side: a support line below
stopPrice = lineValue - overshootAllowanceTicks * tickSize;
exitLongIfStopHit = low[0] <= stopPrice;

mismatchedShortSetupLevel = low[0]; // the level a low-N short would have used as its stop-entry trigger
limitPrice = mismatchedShortSetupLevel;
enterLongOnLimitNextBar = isBullChannel[0] && (isLow1SetupSignalBar[0] || isLow2SetupSignalBar[0] || isLow3SetupSignalBar[0] || isLow4SetupSignalBar[0]) && low[1] <= limitPrice;

isInsideBar2 = high[2] < high[3] && low[2] > low[3];
isIiPatternAt1 = isInsideBar2 && (high[1] < high[2] && low[1] > low[2]);
isIiiPattern = isIiPatternAt1 && (high[0] < high[1] && low[0] > low[1]);
iiiPatternBottom = min(low[0], min(low[1], low[2]));
